<template><el-dialog v-model="visible" title="生产工单完整流程" width="min(1400px,96vw)" class="storage-dialog" :before-close="close" :close-on-click-modal="false"><OperationStatus :operation="operation"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button><div v-loading="loading" v-if="data"><el-descriptions :column="3" border><el-descriptions-item label="工单号">{{data.order?.orderNo||data.order?.number||data.order?.order_no}}</el-descriptions-item><el-descriptions-item label="客户">{{data.order?.customerName||data.order?.customer||data.order?.customer_name}}</el-descriptions-item><el-descriptions-item label="状态">{{orderStates[data.order?.status]||data.order?.status}}</el-descriptions-item><el-descriptions-item label="所属工厂">{{data.order.factoryName}}</el-descriptions-item><el-descriptions-item label="产线">{{data.order.lineName}}</el-descriptions-item><el-descriptions-item label="负责人">{{data.order.ownerName}}</el-descriptions-item><el-descriptions-item label="加工类型">{{processingTypes[data.order.processingType]||data.order.processingType}}</el-descriptions-item><el-descriptions-item v-if="data.order.processingType==='MATERIAL_CUSTOM'" label="客户来料净重（g）">{{data.order.incomingWeight}}</el-descriptions-item><el-descriptions-item label="开单日期">{{data.order.orderDate?.slice(0,10)}}</el-descriptions-item><el-descriptions-item label="创建人">{{data.order.creatorName}}</el-descriptions-item><el-descriptions-item label="客户公司">{{customerSnapshot.companyName}}</el-descriptions-item><el-descriptions-item label="客户地址">{{customerSnapshot.address}}</el-descriptions-item><el-descriptions-item label="客户联系方式">{{customerSnapshot.contactName}} {{customerSnapshot.contactPhone}}</el-descriptions-item></el-descriptions>
 <div class="actions"><el-button v-if="can('metal:work-order:execute')" :disabled="finished||operation.busy.value||!!operation.pending.value" @click="complete">工单正常完工</el-button><el-button v-if="can('metal:work-order:exception-close')" type="warning" :disabled="finished||operation.busy.value||!!operation.pending.value" @click="exceptionOpen=true">申请异常完工</el-button><el-button @click="load">刷新流程</el-button></div>
 <el-tabs v-model="tab"><el-tab-pane label="加工路线与批次" name="flow"><div v-for="item in data.items||[]" :key="item.id"><h3>{{item.product?.name||item.productName}} · 计划 {{item.quantity}} 件</h3><el-table :data="item.steps||item.processes||[]" border><el-table-column prop="sequenceNo" label="顺序" width="65"/><el-table-column prop="processName" label="工序" min-width="110"/><el-table-column label="处理规则"><template #default="{row}">{{labels[row.semanticCode]||row.semanticCode}}</template></el-table-column><el-table-column label="产出类别"><template #default="{row}">{{labels[row.outputCategory]||row.outputCategory}}</template></el-table-column><el-table-column label="计量"><template #default="{row}">{{labels[row.measurementMode]||row.measurementMode}}</template></el-table-column><el-table-column prop="acceptedWeight" label="已确认产出（g）"/><el-table-column label="完成件数 / 参考"><template #default="{row}">{{row.acceptedQuantity??'—'}}{{row.completedQuantityKind==='REFERENCE'?'（参考）':''}}</template></el-table-column><el-table-column prop="nextIssuedWeight" label="后续已领（g）"/><el-table-column prop="availableWeight" label="可领取（g）"/><el-table-column prop="inProcessWeight" label="在制（g）"/><el-table-column prop="openBatchCount" label="未结批次"/><el-table-column label="生产领料" width="110"><template #default="{row}"><el-button v-if="can('metal:warehouse-order:add')" :disabled="row.executionClosed||finished||loading||operation.busy.value||!!operation.pending.value" @click="issueStage(item,row)">生产领料</el-button></template></el-table-column><el-table-column label="工序完成" width="120"><template #default="{row}"><el-button v-if="can('metal:work-order:execute')" :disabled="row.executionClosed||finished||operation.busy.value||!!operation.pending.value" @click="completeStep(row)">{{row.executionClosed?'已完成':'完成工序'}}</el-button></template></el-table-column></el-table></div><ProductionBatchPanel ref="batchPanel" :factory-id="props.factoryId" :order-id="id" :items="data.items||[]" :disabled="finished||operation.busy.value||!!operation.pending.value"/><h3>工序加工记录与物料平衡</h3><el-table :data="executionRows" border class="execution-table"><el-table-column prop="number" label="加工记录编号" min-width="140"/><el-table-column label="生产批次" min-width="150"><template #default="{row}">{{row.legacyAdopted?`已承接 → PB #${row.targetBatchId}`:row.batchNumber||(row.batchId?`PB身份 #${row.batchId}`:'历史未映射')}}</template></el-table-column><el-table-column label="历史写入保护" min-width="220"><template #default="{row}"><span v-if="row.readOnly">{{row.writeBlockedReason||'历史记录未映射可靠生产批次，仅供查询'}}</span><span v-else>—</span></template></el-table-column><el-table-column prop="processName" label="工序" min-width="110"/><el-table-column prop="processorName" label="加工人员" min-width="125"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='OPEN'?'primary':row.status==='CLOSED'?'success':'info'" effect="light">{{row.legacyAdopted?'历史已承接':row.status==='OPEN'&&row.started===false?'未开始':labels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column v-for="c in balanceColumns" :key="c.key" :prop="c.key" :label="c.label" min-width="115"/><el-table-column label="操作" width="270" fixed="right"><template #default="{row}"><div class="batch-actions"><el-button v-if="can('metal:warehouse-order:add')" :disabled="row.readOnly===true||row.status!=='OPEN'" class="list-action list-action--row list-action--primary" @click="document(row,'OUT')">补料</el-button><el-button v-if="can('metal:warehouse-order:add')" :disabled="row.readOnly===true||row.status!=='OPEN'" class="list-action list-action--row list-action--edit" @click="document(row,'IN')">产出入库</el-button><el-button v-if="can('metal:warehouse-order:add')" :disabled="row.readOnly===true||row.status!=='OPEN'" class="list-action list-action--row list-action--primary" @click="document(row,'RET')">还库</el-button><el-button v-if="can('metal:work-order:execute')" :disabled="row.readOnly===true||row.status!=='OPEN'" class="list-action list-action--row list-action--edit" @click="closeBatch(row)">结束本工序</el-button></div></template></el-table-column></el-table></el-tab-pane>
 <el-tab-pane label="仓储单据" name="documents"><el-table :data="data.documents||[]" border><el-table-column prop="number" label="单据编号"/><el-table-column label="类型"><template #default="{row}">{{typeNames[row.type]||row.type}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{statusNames[row.status]||row.status}}</template></el-table-column><el-table-column prop="createdAt" label="创建时间"/><el-table-column label="操作"><template #default="{row}"><el-button @click="showStorage(row)">查看单据</el-button></template></el-table-column></el-table></el-tab-pane>
 <el-tab-pane label="报工与损耗" name="report"><el-button v-if="can('metal:material-debt:list')" @click="debtsOpen=true">本工单材料借还账</el-button><el-descriptions v-if="report?.orderTotals" :column="3" border><el-descriptions-item v-for="c in totalColumns" :key="c.key" :label="c.label">{{report.orderTotals[c.key]??'—'}}</el-descriptions-item></el-descriptions><el-alert title="各加工阶段分别核对投入、产出、退料、回收及损耗；阶段投入合计不等于外部来料净耗用量。" type="info" :closable="false"/><el-table :data="report?.executions||[]" border><el-table-column prop="id" label="加工记录"/><el-table-column v-for="c in balanceColumns" :key="c.key" :prop="c.key" :label="c.label"/><el-table-column label="客户料投入"><template #default="{row}">{{row.sourceCompositionKnown===false?'来源未知':row.customerInputWeight??'—'}}</template></el-table-column><el-table-column label="厂方供料（含他客借入）"><template #default="{row}">{{row.sourceCompositionKnown===false?'来源未知':row.factoryInputWeight??'—'}}</template></el-table-column><el-table-column prop="customerLossWeight" label="客户承担损耗"/><el-table-column prop="factoryLossWeight" label="工厂承担损耗"/></el-table><p v-for="(note,index) in report?.notices||[]" :key="index">{{note}}</p></el-tab-pane>
 <el-tab-pane label="流转记录" name="events"><el-timeline><el-timeline-item v-for="(event,index) in data.events||[]" :key="event.id||index" :timestamp="String(event.createTime||event.createdAt||event.create_time||'').replace('T',' ')">{{labels[event.action||event.type||event.event_type]||event.action||event.type||event.event_type}} · 单据 {{event.documentId||event.document_id}} · {{event.weight}} g · {{event.actorName||event.operatorName}} {{event.reason||event.description}}</el-timeline-item></el-timeline><el-table v-if="data.exceptionClosures?.length" :data="data.exceptionClosures" border><el-table-column prop="reason" label="异常完工原因"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='OPEN'?'primary':row.status==='CLOSED'?'success':'info'" effect="light">{{labels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="审批"><template #default="{row}"><el-button v-if="row.canReview&&can('metal:work-order:exception-review')" @click="reviewException(row,true)">批准</el-button><el-button v-if="row.canReview&&can('metal:work-order:exception-review')" @click="reviewException(row,false)">退回</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></div>
 <template #footer><el-button :disabled="operation.busy.value||!!operation.pending.value" @click="close()">关闭</el-button></template>
 <el-dialog v-model="exceptionOpen" title="申请异常完工" width="600px" append-to-body :close-on-click-modal="false"><OperationStatus :operation="operation"/><p>不足数量和当前物料余额仍保留，异常完工不会自动填平库存或欠料。</p><el-form label-position="top"><el-form-item label="指定审批人员" required><el-select v-model="exception.reviewerId"><el-option v-for="p in state.people.filter(p=>String(p.id)!==String(user.id))" :key="p.id" :label="p.name||p.nickName" :value="p.id"/></el-select></el-form-item><el-form-item label="异常原因" required><el-input v-model="exception.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="exceptionOpen=false">取消</el-button><el-button :loading="operation.busy.value" :disabled="!!operation.pending.value||!exception.reviewerId||!exception.reason.trim()" @click="applyException">提交审批</el-button></template></el-dialog>
<BatchCloseDialog ref="closeDialog" :factory-id="props.factoryId" :order-id="id" :refresh="refreshAfterClose" @documents="tab='documents'"/>
 <OrderEditor ref="editor" @saved="load"/><DebtPanel v-model="debtsOpen" :order-id="id" @repay="row=>{debtsOpen=false;editor?.open('RETURN_RIGHTS',undefined,{debt:row})}"/>
</el-dialog></template>
<script setup lang="ts">
import ProductionBatchPanel from './ProductionBatchPanel.vue';import DebtPanel from '../storage-live/DebtPanel.vue';import BatchCloseDialog from './BatchCloseDialog.vue';import {computed,ref} from 'vue';import {ElMessageBox} from 'element-plus';import {useRouter} from 'vue-router';import request from '@/utils/request';import {useStorage,useOperation,message,type Row} from '../storage-live/client';import OperationStatus from '../storage-live/OperationStatus.vue';import OrderEditor from '../storage-orders/OrderEditor.vue';import {typeNames,statusNames} from '../storage-orders/model'
const props=defineProps<{factoryId:string}>(),emit=defineEmits<{changed:[]}>(),{state,user,can,context,loadOptions}=useStorage(),router=useRouter(),visible=ref(false),id=ref(''),data=ref<any>(),report=ref<any>(),error=ref(''),loading=ref(false),tab=ref('flow'),exceptionOpen=ref(false),editor=ref<InstanceType<typeof OrderEditor>>()
const debtsOpen=ref(false)
const batchPanel=ref<InstanceType<typeof ProductionBatchPanel>>()
const processingTypes:Record<string,string>={MATERIAL_CUSTOM:'来料定制',DIRECT_CUSTOM:'直接定制',SHORTAGE_CUSTOM:'欠料定制'}
const closeDialog=ref<InstanceType<typeof BatchCloseDialog>>()
async function refreshAfterClose(){await load();emit('changed');return !error.value}
const balanceColumns=[{key:'inputWeight',label:'投入（g）'},{key:'outputWeight',label:'产出（g）'},{key:'carryInWeight',label:'在制承接（g）'},{key:'carryOutWeight',label:'在制移交（g）'},{key:'returnedWeight',label:'原样退回（g）'},{key:'recoveredWeight',label:'回收料（g）'},{key:'lossWeight',label:'损耗（g）'}]
const labels:Record<string,string>={INPUT:'领料投入',OUTPUT:'产出入库',RETURN:'原料还库',RECOVERY:'回收料入库',NORMAL:'普通工艺',ACID_WASH:'酸洗',SMELTING:'融定',RAW:'原材料',SEMI:'半成品',PRODUCT:'成品',WEIGHT:'计重',PIECE:'计件',OPEN:'加工中',CLOSED:'已结清',CANCELLED:'已取消',SPLIT_TRANSFERRED:'已移交'}
const totalColumns=[{key:'externalInputWeight',label:'整单外部净投入（g）'},{key:'finalOutputWeight',label:'成品产出（g）'},{key:'originalReturnWeight',label:'原料归还（g）'},{key:'recoveredWeight',label:'回收料（g）'},{key:'lossWeight',label:'加工损耗（g）'},{key:'inProcessWeight',label:'在制余额（g）'},{key:'intermediateStockWeight',label:'中间库存（g）'},{key:'handoverLossWeight',label:'交接损失（g）'},{key:'transferredToOtherOrdersWeight',label:'转出其他工单净重（g）'},{key:'intermediateDispatchWeight',label:'中间料出厂实收（g）'},{key:'balanceDifferenceWeight',label:'整单平衡差（g）'}]
const orderStates:Record<string,string>={CREATED:'已创建',IN_PROGRESS:'加工中',COMPLETED:'已完工',EXCEPTION_COMPLETED:'异常完工'}
const finished=computed(()=>['COMPLETED','EXCEPTION_COMPLETED'].includes(data.value?.order?.status)),customerSnapshot=computed(()=>{try{return JSON.parse(data.value?.order?.customerSnapshot||'{}')}catch{return {}}}),executionRows=computed(()=>(data.value?.executions||[]).map((e:any)=>({...e,number:e.number||String(e.id),processName:e.processName||data.value?.items?.flatMap((i:any)=>i.steps||[]).find((s:any)=>String(s.id||s.orderStepId)===String(e.orderStepId))?.processName||String(e.orderStepId),processorName:e.processorName||state.people.find(p=>p.id===String(e.processorId))?.name||String(e.processorId)})))
const exception=ref({reviewerId:'',reason:''});let epoch=0
const operation=useOperation('/metal/production-order/executions',context,async()=>{exceptionOpen.value=false;emit('changed');await load()})
async function open(orderId:string){debtsOpen.value=false;id.value=orderId;state.factoryId=props.factoryId;visible.value=true;tab.value='flow';await load();if(can('metal:work-order:execute')||can('metal:warehouse-order:add')||can('metal:work-order:exception-close'))await loadOptions()}
async function load(){const current=context(),order=id.value,req=++epoch;loading.value=true;error.value='';try{const [f,r]:any[]=await Promise.all([request({url:`/metal/production-order/${order}/flow`,params:{factoryId:props.factoryId},quiet:true}),request({url:`/metal/production-order/${order}/report`,params:{factoryId:props.factoryId},quiet:true})]);if(current===context()&&req===epoch){data.value=f.data;report.value=r.data;void batchPanel.value?.load()}}catch(e){if(req===epoch)error.value=message(e)}finally{if(req===epoch)loading.value=false}}
function closeBatch(row:Row){if(operation.busy.value||operation.pending.value||batchPanel.value?.isLocked())return;closeDialog.value?.open(row)}
async function completeStep(step:Row){if(batchPanel.value?.isLocked())return;const current=context(),order=id.value,version=data.value.order.version;try{await ElMessageBox.confirm('确认完成本工序？完成后不能再新建该工序加工批次，服务端将核对产出与未结事项。','完成工序')}catch{return}if(current===context()&&order===id.value){await operation.send(`/metal/production-order/${order}/steps/${step.id}/complete`,{factoryId:props.factoryId,version});if(current===context()&&order===id.value&&operation.error.value)await ElMessageBox.alert(operation.error.value,`${step.processName||'当前工序'}完成失败`,{type:'error',confirmButtonText:'我知道了',closeOnClickModal:false,closeOnPressEscape:false})}}
async function complete(){if(batchPanel.value?.isLocked())return;try{await ElMessageBox.confirm('确认按计划数量完成本工单？所有加工批次及单据必须已结清。','正常完工')}catch{return}void operation.send(`/metal/production-order/${id.value}/complete`,{factoryId:props.factoryId,version:data.value.order.version})}
function applyException(){if(batchPanel.value?.isLocked())return;void operation.send(`/metal/production-order/${id.value}/exception-close`,{factoryId:props.factoryId,version:data.value.order.version,...exception.value})}
async function reviewException(row:Row,approve:boolean){try{const r=await ElMessageBox.prompt('请输入审批说明','异常完工审批',{inputValidator:v=>!!v?.trim()||'请输入说明'});void operation.send(`/metal/production-order/${id.value}/exception-close/${row.id}/review`,{factoryId:props.factoryId,version:row.version,approve,reason:r.value})}catch{}}
function issueStage(item:any,step:Row){if(finished.value||loading.value||operation.busy.value||operation.pending.value||batchPanel.value?.isLocked()||!can('metal:warehouse-order:add')||step.executionClosed)return;void editor.value?.open('OUT',undefined,{orderId:id.value,orderItemId:String(item.id),orderStepId:String(step.id),type:'PRODUCTION_OUT'})}
function document(row:Row,kind:'OUT'|'IN'|'RET'){if(batchPanel.value?.isLocked())return;const type=kind==='OUT'?'PRODUCTION_OUT':kind==='RET'?'RAW_RETURN':row.outputCategory==='RAW'?'PROCESS_RAW_IN':row.outputCategory==='PRODUCT'?'PRODUCT_IN':'SEMI_IN';editor.value?.open(kind,undefined,{orderId:id.value,batchId:row.batchId||'',batchVersion:row.batchVersion,executionId:row.id,executionVersion:row.version,type})}
function showStorage(row:Row){visible.value=false;void router.push({path:'/metal/storage-orders',query:{factoryId:props.factoryId,detail:row.id}})}
async function close(done?:()=>void){if(operation.busy.value||operation.pending.value)return;if(batchPanel.value&&!batchPanel.value.requestClose())return;if(closeDialog.value&&!closeDialog.value.requestClose())return;if(editor.value&&!await editor.value.requestClose())return;visible.value=false;done?.()}
watch(()=>props.factoryId,()=>{epoch++;debtsOpen.value=false;visible.value=false});defineExpose({open})
</script><style scoped>.actions{display:flex;gap:10px;margin:16px 0 8px;flex-wrap:wrap}h3{font-size:15px;margin:20px 0 12px}.el-select{width:100%}.batch-actions{display:grid;grid-template-columns:repeat(3,max-content);gap:8px;padding:4px 0}.batch-actions .el-button{margin:0}.batch-actions .el-button:last-child:nth-child(6){grid-column:auto}.execution-table :deep(.cell){word-break:normal;overflow-wrap:anywhere}.execution-table :deep(.el-table__cell){padding:10px 0}</style>
